    "description": "Готовьтесь, банда любителей морей и угарных тусовок снова в деле! Ио́ри и его банда по грандиозным пьянкам и редким погружениям готовы зажечь на полную катушку. В этот раз их безумная любовь к приключениям, алкоголю и рок-н-роллу занесёт всю эту дикую компанию в незабываемое путешествие за границу.\r\nРебят ждёт поездка на райские тропические острова Пала́у, где море нереально красивое, а места для ныряния — просто космос. Но никакого приличного отдыха не будет! Героев по традиции ждут дикие приколы, новые знакомства и тонны весёлого хаоса, ведь эти чуваки просто физически не умеют вести себя адекватно.",
    "air_timestamp": 1790110800000
