    "media_type": "anime-series",
    "source": "anilibria",
    "description": "Жизнь обычного старшеклассника сродни аду из-за редкой аномалии: он притягивает паранормальщину в целых шесть раз сильнее, чем другие люди. Вечный кошмар прекращается, когда парень сталкивается с Меча́ко — дерзкой девчонкой, возглавляющей подпольную банду по борьбе с нечистой силой.\r\nНедолго думая, Меча́ко превращает ходячий магнит для духов в живую приманку. Пугливого героя швыряют в самый центр безумных разборок с доппельгангерами, проклятыми куклами и агрессивными монстрами. Ему остаётся только заглушить страх и вместе со своими новыми коллегами навести порядок на ночных улицах. Вперёд, отряд мистики!",
