    "description": "Приключения Берила Гарденанта в столице продолжаются. Скромный деревенский учитель, упрямо считающий себя посредственным мечником, окончательно закрепился в роли инструктора рыцарского ордена. Его выдающиеся ученики, ставшие сильнейшими воинами королевства, по прежнему не дают наставнику покоя, втягивая его в новые события.\r\nВпереди Берила ждут опасные вызовы, охрана высокопоставленных лиц и заговоры знати. И пока враги недооценивают пожилого «деревенщину», сам мастер продолжит демонстрировать непревзойдённое искусство фехтования, искренне удивляясь, почему все вокруг считают его легендой.",
