    "description": "Старшеклассница И́то жила свою обычную жизнь, была единственным ребёнком в семье, и, казалось бы, ничего не предвещало беды. Но вот однажды мама Ито не решила выйти замуж во второй раз и переехать в другой город, следуя зову сердца.\r\nЗвучит вполне себе обычно, бедобидно и даже романтично, если бы не то обстоятельство, что в новой семье у Ито появляется аж четыре сводных младших брата! Ну что ж, будет интересно понаблюдать за семейной жизнью новоиспечённой старшей сестры.",
