    "description": "Брат и сестра, Хина́та и Као́ру, случайно набрели во время шторма на заброшенное святилище и разбудили заточённое там зловещее существо. Перед детьми предстал кошмарный змей-оборотень, встреча с которым веками означала для людей верную смерть.\r\nВот только современные дети напрочь лишены суеверий. Совершенно невозмутимые подростки нагло проигнорировали грозный статус монстра, ласково окрестили его Дарочкой и начали регулярно наведываться к нему в гости. Древнему духу проклятий не осталось ничего другого, кроме как примерить роль няньки и терпеть бесконечные подколы со стороны этой бесстрашной парочки.",
