    "description": "Япония, начало двадцатоговека. Военный курсант Ко́до Ивамо́то колесит по глухим уголкам страны с секретной миссией от Императорской армии. Он ищет людей со сверхъестественными способностями, чтобы выдать им рекомендацию в закрытую академию. Его задача — превратить опасных одиночек в живое оружие на службе у государства.\r\nПоиски бросают Ивамото в эпицентр пугающих аномалий, от деревень с чёрным снегом до жутких ритуалов. Столкиваясь с обладателями паранормальных сил, парень не просто выполняет приказы штаба. Он ввязывается в опасные расследования, спасая этих изгоев от безумия и жестокого мира, который считает их проклятыми.",
