    "source": "anilibria",
    "description": "Двести лет назад русалка Ла́ра, как это часто бывает с представителями её рода, превратилась в морскую пену из-за безответной любви к принцу. Но судьба дала ей второй шанс, и девушка переродилась в теле человека у берегов современной Японии. Теперь её цель — найти того, чьи искренние чувства помогут окончательно снять древнее проклятие.\r\nОказавшись в незнакомом мире, бывшая морская принцесса вынуждена с нуля учиться выживать среди поездов, супермаркетов и строгих школьных правил. В этом ей помогает прямолинейная старшеклассница-боксёр. Но привычный уклад рушится, когда Ла́ра случайно встречает парня по имени Лу́ка, который как две капли воды похож на её возлюбленного из далёкого прошлого.",
